package net.oceancanvas.mod.worldgen;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class OceanCanvasStablePhysicalRecoveryTest {
 @Test void setRevisionCoversEveryStructuralWriterAndIgnoresNoops(){var s=new OceanCanvasPrimitiveLongSet();long v=s.membershipVersion();assertFalse(s.remove(1));s.clear();assertEquals(v,s.membershipVersion());s.add(1);assertTrue(s.membershipVersion()>v);v=s.membershipVersion();s.add(1);assertEquals(v,s.membershipVersion());s.add(2);v=s.membershipVersion();s.removeIf(k->k==1);assertTrue(s.membershipVersion()>v);v=s.membershipVersion();s.drainFirst(1);assertTrue(s.membershipVersion()>v);s.add(3);v=s.membershipVersion();s.clear();assertTrue(s.membershipVersion()>v);}
 @Test void mapRevisionTracksKeysNotDelayValues(){var m=new OceanCanvasPrimitiveLongIntMap();long v=m.membershipVersion();m.put(1,3);assertTrue(m.membershipVersion()>v);v=m.membershipVersion();m.put(1,4);m.incrementCapped(1,8);m.remove(9);assertEquals(v,m.membershipVersion());m.incrementCapped(2,8);assertTrue(m.membershipVersion()>v);v=m.membershipVersion();m.remove(1);assertTrue(m.membershipVersion()>v);v=m.membershipVersion();m.clear();assertTrue(m.membershipVersion()>v);}
 @Test void stableObservationReusesButOwnRepairsRequireFreshFullPass(){var p=new OceanCanvasPregenFlattenerSession(2,0);var s=new OceanCanvasLightFinalizerSession();for(long k=0;k<12000;k++)s.pendingTicks.put(k,1);p.PREGEN_CRASH_RECOVERY_PHYSICAL_TRACKED.add(1);assertEquals(1,OceanCanvasPhysicalRecoveryReconciler.reconcile(p,s));OceanCanvasPhysicalRecoveryReconciler.reconcile(p,s);for(int i=0;i<100;i++)OceanCanvasPhysicalRecoveryReconciler.reconcile(p,s);assertEquals(2,s.physicalReconciliationScans.get());assertEquals(100,s.physicalReconciliationCacheHits.get());s.pendingTicks.put(1,9);OceanCanvasPhysicalRecoveryReconciler.reconcile(p,s);assertEquals(2,s.physicalReconciliationScans.get());assertEquals(9,s.pendingTicks.get(1));}
 @Test void allSixMembershipInputsInvalidate(){for(int input=0;input<6;input++){var p=new OceanCanvasPregenFlattenerSession(2,0);var s=new OceanCanvasLightFinalizerSession();s.pendingTicks.put(1,1);p.PREGEN_CRASH_RECOVERY_PHYSICAL_TRACKED.add(1);OceanCanvasPhysicalRecoveryReconciler.reconcile(p,s);OceanCanvasPhysicalRecoveryReconciler.reconcile(p,s);long scans=s.physicalReconciliationScans.get();switch(input){case 0->s.pendingTicks.put(2,1);case 1->{p.PREGEN_CRASH_RECOVERY_PHYSICAL_TRACKED.remove(1);p.PREGEN_CRASH_RECOVERY_PHYSICAL_TRACKED.add(2);}case 2->p.PREGEN_CRASH_RECOVERY_PHYSICAL_TERRAIN_SAFE.add(1);case 3->p.PREGEN_CRASH_RECOVERY_PHYSICAL_ACTIVE.remove(1);case 4->p.PREGEN_CRASH_RECOVERY_LIGHT_ONLY_TRACKED.add(1);case 5->p.PREGEN_CRASH_RECOVERY_LIGHT_ONLY_ACTIVE.add(1);}OceanCanvasPhysicalRecoveryReconciler.reconcile(p,s);assertTrue(s.physicalReconciliationScans.get()>scans,"input"+input);}}
 @Test void equalRevisionsFromDifferentOwnerCannotReuse(){var a=new OceanCanvasPregenFlattenerSession(2,0);var b=new OceanCanvasPregenFlattenerSession(2,0);var s=new OceanCanvasLightFinalizerSession();s.pendingTicks.put(7,1);a.PREGEN_CRASH_RECOVERY_PHYSICAL_TRACKED.add(7);b.PREGEN_CRASH_RECOVERY_PHYSICAL_TRACKED.add(9);OceanCanvasPhysicalRecoveryReconciler.reconcile(a,s);OceanCanvasPhysicalRecoveryReconciler.reconcile(a,s);long scans=s.physicalReconciliationScans.get();OceanCanvasPhysicalRecoveryReconciler.reconcile(b,s);assertTrue(s.physicalReconciliationScans.get()>scans);assertFalse(b.PREGEN_CRASH_RECOVERY_PHYSICAL_ACTIVE.contains(7));}
 @Test void concurrentMembershipChangesCannotStayCachedAfterJoin()throws Exception{var p=new OceanCanvasPregenFlattenerSession(2,0);var s=new OceanCanvasLightFinalizerSession();s.pendingTicks.put(1,1);OceanCanvasPhysicalRecoveryReconciler.reconcile(p,s);Thread producer=Thread.ofPlatform().start(()->{for(int i=0;i<5000;i++){p.PREGEN_CRASH_RECOVERY_PHYSICAL_TRACKED.add(1);p.PREGEN_CRASH_RECOVERY_PHYSICAL_TRACKED.remove(1);}p.PREGEN_CRASH_RECOVERY_PHYSICAL_TRACKED.add(1);});for(int i=0;i<100;i++)OceanCanvasPhysicalRecoveryReconciler.reconcile(p,s);producer.join(5000);assertFalse(producer.isAlive());OceanCanvasPhysicalRecoveryReconciler.reconcile(p,s);assertTrue(p.PREGEN_CRASH_RECOVERY_PHYSICAL_ACTIVE.contains(1));assertTrue(s.pendingTicks.containsKey(1));}
}
